<script setup lang="ts">
import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {api,type Payment,type Page,type Receipt,type Journal} from '../api';import {usePoll} from '../composables/poll';import {money,time} from '../money';import DataState from '../components/DataState.vue';import StatusBadge from '../components/StatusBadge.vue';
const route=useRoute();const status=ref(String(route.query.status??''));const page=ref(1);const selected=ref<string|null>(null);const detail=ref<{payment?:Payment;journals?:Journal[];receipt?:Receipt;notifications?:{message:string;createdAt:string}[]}>();const detailError=ref('');
const state=usePoll(signal=>api<{payments:Page<Payment>;receipts:Page<Receipt>}>(`/payment-journeys?page=${page.value}`,{signal}));
const rows=computed(()=>{const map=new Map(state.data.value?.payments.items.map(p=>[p.bankTransactionId,{...p,receipt:state.data.value?.receipts.items.find(r=>r.bankTransactionId===p.bankTransactionId)}]));for(const r of state.data.value?.receipts.items??[])if(!map.has(r.bankTransactionId))map.set(r.bankTransactionId,{id:r.id,eventId:r.eventId,bankTransactionId:r.bankTransactionId,originalReference:r.paymentReference,resolvedReference:null,bankOutcome:r.bankOutcome,amountMinor:r.amountMinor,status:'Pending',reason:null,paidAt:r.paidAt,receivedAt:r.receivedAt,appliedAt:null,attempts:0,lateReview:false,correlationId:r.correlationId,allocations:[],receipt:r});return [...map.values()].filter(p=>!status.value||p.status===status.value||(status.value==='Duplicate'&&(p.receipt?.attempts??0)>1))});
async function open(transactionId:string){selected.value=transactionId;detail.value=undefined;detailError.value='';try{const [p,r,n]=await Promise.all([api<{payment:Payment;journals:Journal[]}>(`/payments/${transactionId}`).catch(()=>null),api<Page<Receipt>>(`/receipts?transactionId=${transactionId}`),api<{message:string;createdAt:string}[]>(`/notifications?transactionId=${transactionId}`)]);detail.value={...p,receipt:r.items[0],notifications:n}}catch(e){detailError.value=e instanceof Error?e.message:'Detail unavailable'}}
</script>
<template><div class="page-title"><div><p class="eyebrow">DURABLE ACCEPTANCE → EVENTUAL ALLOCATION</p><h1>Payments & webhooks</h1><p class="muted">Bank outcome, webhook receipt, financial allocation and notification remain distinct.</p></div></div><DataState :loading="state.loading.value" :error="state.error.value" :updated-at="state.updatedAt.value"/><section class="panel"><div class="panel-heading"><div><h3>Observed transactions</h3><p>Status filters apply to the current page of 50 unique transactions.</p></div><el-select v-model="status" clearable placeholder="Filter statuses on this page" class="search"><el-option v-for="s in ['Pending','Applied','AppliedWithCredit','Duplicate','Unmatched','BankDeclined']" :key="s" :label="s" :value="s"/></el-select></div><el-table :data="rows" class="clickable-table" @row-click="(row:Payment)=>open(row.bankTransactionId)"><el-table-column label="Bank identity / loan" min-width="275"><template #default="{row}"><strong class="identity">{{row.bankTransactionId}}</strong><small class="table-sub">{{row.originalReference}}</small></template></el-table-column><el-table-column label="Amount" min-width="155"><template #default="{row}">{{money(row.amountMinor)}}</template></el-table-column><el-table-column label="Bank outcome" min-width="155"><template #default="{row}"><StatusBadge :status="row.bankOutcome"/></template></el-table-column><el-table-column label="Application" min-width="170"><template #default="{row}"><StatusBadge :status="row.status"/></template></el-table-column><el-table-column label="Paid / received (Bangkok)" min-width="215"><template #default="{row}">{{time(row.paidAt)}}<small class="table-sub">{{time(row.receivedAt)}}</small></template></el-table-column><el-table-column label="Processing time" width="145"><template #default="{row}">{{row.appliedAt?((new Date(row.appliedAt).getTime()-new Date(row.receivedAt).getTime())/1000).toFixed(2)+'s':'Pending'}}</template></el-table-column><el-table-column label="Delivery attempts" width="140"><template #default="{row}">{{row.receipt?.attempts??'Unavailable'}}</template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="50" :total="Math.max(state.data.value?.payments.total??0,state.data.value?.receipts.total??0)" layout="prev,pager,next,total" @current-change="state.refresh"/></section>
<el-drawer :model-value="selected!==null" title="Payment journey" size="620px" @close="selected=null"><p class="identity">{{selected}}</p><el-alert v-if="detailError" :title="detailError" type="error" :closable="false"/><template v-if="detail"><el-timeline><el-timeline-item :timestamp="time(detail.receipt?.receivedAt)"><h3>Durable receipt</h3><StatusBadge :status="detail.receipt?.status??'Unavailable'"/><p>Delivery attempts: {{detail.receipt?.attempts??'Unavailable'}}</p></el-timeline-item><el-timeline-item :timestamp="time(detail.receipt?.outbox?.publishedAt)"><h3>Outbox publication</h3><p>{{detail.receipt?.outbox?.publishedAt?'Publisher confirmation recorded':'Pending or unavailable'}}</p></el-timeline-item><el-timeline-item :timestamp="time(detail.payment?.appliedAt)"><h3>Consumer & allocation</h3><StatusBadge :status="detail.payment?.status??'Pending'"/><p>{{detail.payment?.reason}}</p><p>Observed consumer attempts: {{detail.payment?.attempts??'Unavailable'}}</p><div v-for="(a,index) in detail.payment?.allocations" :key="index">Installment {{a.installmentNumber}} · {{money(a.interest)}} interest · {{money(a.principal)}} principal</div></el-timeline-item><el-timeline-item :timestamp="time(detail.notifications?.[0]?.createdAt)"><h3>In-app notification</h3><p>{{detail.notifications?.[0]?.message??'Not observed yet'}}</p></el-timeline-item></el-timeline><p class="chart-note">Correlation: {{detail.receipt?.correlationId??detail.payment?.correlationId??'Unavailable'}}. Trace viewer data unavailable here; use the configured viewer in Observability.</p><p class="chart-note">Original paidAt UTC: {{detail.payment?.paidAt??detail.receipt?.paidAt}}</p><el-collapse><el-collapse-item v-for="journal in detail.journals" :key="journal.id" :title="journal.kind"><div v-for="(p,index) in journal.postings" :key="index">{{p.account}} · Debit {{money(p.debit)}} · Credit {{money(p.credit)}}</div></el-collapse-item></el-collapse></template></el-drawer></template>
